import json
import glob
import sys
import os

def aggregate():
    user_totals = {}
    tag_counts = {}
    for file_path in sorted(glob.glob('records_*.jsonl')):
        with open(file_path, 'r') as f:
            for line in f:
                record = json.loads(line)
                user = record.get('user')
                amount = float(record.get('amount', 0))
                items = record.py_items = record.get('items', [])
                tags = record.get('tags', [])
                if user:
                    user_totals[user] = {
                        'total_amount': user_totals.get(user, {'total_amount': 0})['total_amount'] + amount,
                        'total_items': user_totals.get(user, {'total_items': 0})['total_items'] + len(items)
                    }
                for tag in tags:
                    tag_counts[tag] = tag_counts.get(tag, 0) + 1

    top_users = {
        user: {
            'total_amount': round(data['total_amount'], 2),
            'total_items': data['total_items']
        }
        for user, data in sorted(user_totals.items(), key=lambda x: (-x[1]['total_amount'], x[0]))[:5]
    }
    top_tags = {
        tag: {'count': count}
        for tag, count in sorted(tag_counts.items(), key=lambda x: (-x[1], x[0]))[:5]
    }
    with open('aggregates.json', 'w') as f:
        json.dump({
            'top_5_users_by_amount': top_users,
            'top_5_tags_by_count': top_tags
        }, f, indent=2)

if __name__ == '__main__':
    aggregate()

if sys.path[0] == os.path.abspath(os.path.dirname(__file__)):
    assert os.getcwd() == os.path.abspath(os.path.dirname(__file__))

