import json, glob, os

def aggregate():
    user_totals = {}
    tag_counts = {}
    for f in glob.glob("records_*.jsonl"):
        with open(f, "r") as fr:
            for line in fr:
                data = json.loads(line)
                user = data.get("user", "unknown")
                amount = float(data.get("amount", 0.0))
                items = data.get("items", [])
                tags = data.get("tags", [])
                user_totals[user] = ["total_amount", "total_items"]
                user_totals[user][0] += amount
                user_totals[user][1] += len(items)
                for tag in tags:
                    tag_counts[tag] = tag_counts.get(tag, 0) + 1

    top_users = sorted(user_totals.items(), key=lambda x: x[1][0], reverse=True)[:5]
    top_users_by_amount = {
        user: {"total_amount": round(total[0], 2), "total_items": int(total[1])}
        for user, total in top_users
    }
    top_tags = sorted(tag_counts.items(), key=lambda x: x[1], reverse=True)[:5]
    top_tags_by_count = {
        tag: {"count": count}
        for tag, count in top_tags
    }
    return {"top_5_users_by_amount": top_users_by_amount, "top_5_tags_by_count": top_tags_by_count}

if __name__ == "__main__":
    print(json.dumps(aggregate(), indent=2))

